solution:
fn main() -> Int {
  let scores = [85, 92, 45, 78];
  var passed = 0;
  for score in scores {
    if score >= 60 {
      passed += 1;
    }
  }
  if passed == 4 {
    io.println("All passed!");
  } else {
    io.println("Some failed.");
  }
  return passed;
}
